    #[test]
    fn sess_suffix_matches_scope_slug_returns_empty() {
        assert_eq!(derive_session_branch_suffix("EPIC-20", "epic-20"), "");
        assert_eq!(derive_session_branch_suffix("PR-6", "pr-6"), "");
    }

    /// branch starts with `<slug>-` → suffix is `#<rest>` (the common
