    #[test]
    fn sess_suffix_batched_branch() {
        assert_eq!(
            derive_session_branch_suffix("EPIC-20", "epic-20-batch7"),
            "#batch7"
        );
        assert_eq!(
            derive_session_branch_suffix("PR-6", "pr-6-review"),
            "#review"
        );
    }

    /// Free-form branch (no scope-slug prefix) → suffix is `@<branch>`.
    #[test]
